 1	function sum(X_val: array<int>, X_crd: array<nat>, v : array<int>, b : int, k : int) : (s : int)
 2	  reads X_val, X_crd, v
 3	  requires X_val.Length >= b >= 0
 4	  requires k <= X_val.Length
 5	  requires X_val.Length == X_crd.Length
 6	  requires forall i :: 0 <= i < (X_crd.Length) - 1 ==> 0 <= X_crd[i] < v.Length
 7	  decreases k - b
 8	  {
 9	    if k <= b then 
10	      0
11	    else  sum(X_val, X_crd, v, b + 1, k) + X_val[b] * v[X_crd[b]]
12	  }
13	
14	
15	method SpMV(X_val: array<int>, X_crd: array<nat>, X_pos: array<nat>, v : array<int>) returns (y : array<int>)
16	  requires X_crd.Length >= 1 
17	  requires X_crd.Length == X_val.Length;
18	  requires forall i, j :: 0 <= i < j < X_pos.Length ==> X_pos[i] <= X_pos[j];
19	  requires forall i :: 0 <= i < X_crd.Length ==> X_crd[i] < v.Length
20	  requires forall i :: 0 <= i < X_pos.Length ==> X_pos[i] <= X_val.Length
21	  requires X_pos.Length >= 1
22	  ensures y.Length + 1 == X_pos.Length
23	  ensures forall i :: 0 <= i < y.Length ==> y[i] == sum(X_val, X_crd, v, X_pos[i], X_pos[i + 1])
24	  {
25	    var N: nat := X_pos.Length - 1;
26	    y := new int[N](i => 0);
27	    var n: nat := 0;
28	    while n < N
29	      invariant n <= y.Length
30	      invariant forall i :: 0 <= i < n ==> y[i] == sum(X_val, X_crd, v, X_pos[i], X_pos[i + 1])
31	      invariant forall i :: n <= i < y.Length ==> y[i] == 0
32	      { 
33	        var k: nat := X_pos[n];
34	        while k < X_pos[n + 1]
35	          invariant k <= X_pos[n + 1]
36	          invariant forall i :: n < i < y.Length ==> y[i] == 0
37	          invariant forall i :: 0 <= i < n ==> y[i] == sum(X_val, X_crd, v, X_pos[i], X_pos[i + 1])
38	          invariant y[n] + sum(X_val, X_crd, v, k, X_pos[n+1]) == sum(X_val, X_crd, v, X_pos[n], X_pos[n+1]) 
39	          {
40	            y[n] := y[n] + X_val[k] * v[X_crd[k]];
41	            k := k + 1;
42	          }
43	        n := n + 1;
44	      }
45	  }
46	
47	
48	// 0 0 0 0 0 0 1 0
49	// 0 0 0 0 0 0 0 0
50	// 0 0 0 0 1 0 0 0
51	// 0 0 0 0 0 0 0 0
52	// 0 0 1 0 0 0 0 0
53	// 0 0 0 0 0 0 0 0
54	// 1 0 0 0 0 0 0 0
55	// 0 0 0 0 0 0 0 0
56	
57	method Main() {
58	  var X_val := new int[4](i => 1);
59	  var X_crd := new nat[4](i => if i <= 3 then (3 - i) * 2 else 0);
60	  var X_pos := new nat[9];
61	  X_pos[0] := 0;
62	  X_pos[1] := 1;
63	  X_pos[2] := 1;
64	  X_pos[3] := 2;
65	  X_pos[4] := 2;
66	  X_pos[5] := 3;
67	  X_pos[6] := 3;
68	  X_pos[7] := 4;
69	  X_pos[8] := 4;
70	
71	  var v := new int[8];
72	
73	  v[0] := 30;
74	  v[1] := 0;
75	  v[2] := 31;
76	  v[3] := 0;
77	  v[4] := 32;
78	  v[5] := 0;
79	  v[6] := 33;
80	  v[7] := 0;
81	
82	  var y := SpMV(
83	    X_val,
84	    X_crd,
85	    X_pos,
86	    v
87	  );
88	
89	  var i := 0;
90	  while i < 8 { print y[i]; print "; "; i := i + 1; }
91	}

